 const double* find_max_address(const double scores[], size_t count){

    size_t max_index{};
    double max{};

    for(size_t i{0}; i < count ; ++i){
        if(scores[i] > max){
            max = scores[i];
            max_index = i;
        }
    }
    return &scores[max_index];
}

